  'advertiser_faq1_a': 'ప్రచారాలకు వెళ్లి "ప్రచారాన్ని సృష్టించండి" పై నొక్కండి. ప్రాథమిక సమాచారాన్ని నమోదు చేయడానికి, మీ 16:9 క్రియేటివ్‌ను అప్‌లోడ్ చేయడానికి, లక్ష్య రవాణా వాహనాలను ఎంచుకోవడానికి, షెడ్యూల్ మరియు బడ్జెట్‌ను కాన్ఫిగర్ చేయడానికి మరియు ధృవీకరణ కోసం సమర్పించడానికి దశల వారీ సెటప్‌ను అనుసరించండి.',
  'advertiser_faq1_q': 'రవాణా ప్రకటన ప్రచారాన్ని ఎలా సృష్టించాలి మరియు ప్రారంభించాలి?',
  'advertiser_faq2_a': 'మేము MP4 (H.264), JPG, PNG మరియు HTML5 జిప్ ప్యాకేజీలకు మద్దతు ఇస్తాము. ప్రామాణిక రిజల్యూషన్ 1920×1080 (16:9 కారక నిష్పత్తి), వీడియో ప్రకటనలకు గరిష్ట వ్యవధి 30 సెకన్లు మరియు ఫైల్ పరిమాణం 50 MB కంటే తక్కువగా ఉండాలి.',
  'advertiser_faq2_q': 'సిఫార్సు చేయబడిన సృజనాత్మక స్పెక్స్ ఏమిటి?',
  'advertiser_faq3_a': 'ప్రతి ప్రచారం ట్రాక్ చేయగల QR గుర్తింపును ఉత్పత్తి చేస్తుంది. ప్రయాణీకులు స్క్రీన్‌పై ప్రదర్శించబడే QR కోడ్‌ను స్కాన్ చేసినప్పుడు, సిస్టమ్ సమయం, స్థానం, వాహన ID ని నమోదు చేస్తుంది మరియు వారిని మీ ల్యాండింగ్ పేజీకి దారి మళ్లిస్తుంది.',
  'advertiser_faq3_q': 'స్మార్ట్ QR కోడ్ లీడ్ అట్రిబ్యూషన్ ఎలా పని చేస్తుంది?',
  'advertiser_faq4_a': 'ప్రచారాలు రోజువారీ లేదా మొత్తం బడ్జెట్ నమూనాపై ఛార్జ్ చేయబడతాయి. ప్రకటన ఖర్చుపై GST (18%) లెక్కించబడుతుంది. ధృవీకరణ ఆమోదం పొందిన తర్వాత పన్ను క్రెడిట్‌లతో కూడిన ఇన్‌వాయిస్‌లు స్వయంచాలకంగా సృష్టించబడతాయి.',
  'advertiser_faq4_q': 'బిల్లింగ్, GST ఇన్‌వాయిస్‌లు మరియు తగ్గింపులు ఎలా పని చేస్తాయి?',
