  'gov_help.faq1_q': 'అన్ని నగర రవాణా డిస్ప్లేలలో అత్యవసర ప్రజా నోటీసును నేను ఎలా ప్రారంభించాలి?',
  'gov_help.faq1_a': 'ప్రసార ప్రకటనలకు వెళ్లండి, "అత్యవసర హెచ్చరిక" ఎంచుకోండి, భౌగోళిక మండలాలు లేదా మార్గాలను నిర్వచించండి, హెచ్చరిక వ్యవధిని సెట్ చేయండి మరియు మీ రెండు-కారకాల ప్రమాణీకరణ పిన్‌తో నిర్ధారించండి.',
  'gov_help.faq2_q': 'ప్రయాణికుల సాంద్రత టెలిమెట్రీ ఎంత తరచుగా నవీకరించబడుతుంది?',
  'gov_help.faq2_a': 'అన్ని మున్సిపల్ మార్గాల్లో ప్రతి 60 సెకన్లకు జీపీఎస్, స్మార్ట్ టికెటింగ్ మరియు స్టాప్ కెమెరా సెన్సార్ల నుండి ప్రయాణీకుల లోడ్ టెలిమెట్రీ సేకరించబడుతుంది.',
  'gov_help.faq3_q': 'రాష్ట్ర ఆడిట్ల కోసం చట్టబద్ధమైన సమ్మతి లాగ్‌లను ఎలా ఎగుమతి చేయాలి?',
  'gov_help.faq3_a': 'సమ్మతి నివేదికలకు నావిగేట్ చేయండి, ఆడిట్ తేదీ పరిధిని ఎంచుకోండి మరియు తారుమారు చేయలేని SHA-256 సంతకం చేసిన CSV లేదా PDF ఆడిట్ బండిల్‌లను ఎగుమతి చేయండి.',
